coverage_validation_harness:
"""Publishes fresh configured selections only after checking prior coverage."""
from collections import defaultdict
import hashlib
import json
import re
from pathlib import Path
import sys
import subprocess

sys.path.insert(0, 'tools/bazel/metadata')
from merge_inventory import merge

root = Path.cwd()
scratch = Path('/tmp/aos-bazel-722')
base_paths = json.loads((scratch / 'cli-feature-configured-inventory-inputs.json').read_text())
inputs = defaultdict(list)
for name, output in base_paths.items():
    path = Path(output) / 'inventory.json'
    if path.is_file():
        inputs[name].append(path)
missing = []
extra_paths = json.loads((scratch / 'cli-feature-inventory-extra-planned-outputs.json').read_text())
subprocess.run([
    '/nix/store/ipbhyg77i2myf03bh1mrnyjkdmn9112b-nix-2.24.12/bin/nix-store',
    '--check-validity', *sorted(set(base_paths.values()) | set(extra_paths)),
], check=True)
for line in extra_paths:
    path = Path(line) / 'inventory.json'
    if not path.is_file():
        missing.append(str(path))
        continue
    stem = Path(line).name.split('-', 1)[1]
    if stem in ['aos-bazel-aos-cli-tests-inventory-1', 'aos-bazel-aos-cli-fleet-tests-inventory-1']:
        name = 'aos-cli'
    else:
        assert stem.startswith('aos-bazel-') and stem.endswith('-feature-repair-extra-inventory-1'), stem
        name = stem.removeprefix('aos-bazel-').removesuffix('-feature-repair-extra-inventory-1')
    inputs[name].append(path)
assert not missing, missing
additional_paths = json.loads((scratch / 'cli-feature-additional-inventory-inputs.json').read_text())
for name, paths in additional_paths.items():
    assert name in base_paths, name
    subprocess.run([
        '/nix/store/ipbhyg77i2myf03bh1mrnyjkdmn9112b-nix-2.24.12/bin/nix-store',
        '--check-validity', *paths,
    ], check=True)
    for output in paths:
        path = Path(output) / 'inventory.json'
        assert path.is_file(), path
        inputs[name].append(path)

staged = {}
report = {}
for name, paths in sorted(inputs.items()):
    output = root / ('tools/bazel/metadata/' + name + '-inventory.json')
    previous = json.loads(output.read_text())
    current = merge(root, [json.loads(path.read_text()) for path in paths])
    def canonical_label(label):
        if name == 'aos-cli' and any(label.startswith(
                '@@+aos_tools_repository+aos_aos_cli_' + profile + '_crates__' + package + '-' + version + '//:')
                for profile in ['tests','fleet_tests']
                for package,version in [('getrandom','0.4.2'),('hashbrown','0.17.1'),('itertools','0.14.0')]):
            return re.sub(r'__aos_(target|exec)(?=_|$)', '', label)
        return label
    previous_labels = {canonical_label(row['label']) for row in previous['configured_targets']}
    current_labels = {canonical_label(row['label']) for row in current['configured_targets']}
    checks = {
        'targets': set(previous['targets']) <= set(current['targets']),
        'source_files': set(previous['source_files']) <= set(current['source_files']),
        'source_directories': set(previous['source_directories']) <= set(current['source_directories']),
        'configured_labels': previous_labels <= current_labels,
    }
    if not all(checks.values()):
        missing = {field: sorted(set(previous[field]) - set(current[field]))
                   for field in ['targets','source_files','source_directories']}
        missing['configured_labels'] = sorted(previous_labels - current_labels)
        raise ValueError('missing prior configured source coverage: ' + name + ' ' + json.dumps(missing))
    # Retain every package/version/feature/platform unit. Generated output paths
    # and environment store paths can change with declared tool/repository inputs.
    def units(value):
        return {(canonical_label(row['label']), row['kind'], row['version'], row['target_cpu'], tuple(row['features']))
                for row in value['configured_targets']}
    absent = units(previous) - units(current)
    repaired = []
    if absent and name == 'aos-cli':
        identities = {('rand','0.8.6')}
        rows = {unit: row for row in previous['configured_targets']
                for unit in [(canonical_label(row['label']),row['kind'],row['version'],row['target_cpu'],tuple(row['features']))]}
        for unit in sorted(absent):
            row = rows[unit]
            name_tag = [tag.removeprefix('crate-name=') for tag in row['tags'] if tag.startswith('crate-name=')]
            assert row['external'] and row['kind'] == 'rust_library', row
            assert name_tag and (name_tag[0],row['version']) in identities, row
            assert any(row['label'].startswith('@@+aos_tools_repository+aos_aos_cli_' + profile + '_crates__')
                       for profile in ['tests','fleet_tests']), row
            repaired.append({'label':row['label'],'version':row['version'],'previous_features':row['features']})
        gate_paths = json.loads((scratch / 'cli-effective-build-profile-qualification-paths.json').read_text())
        for profile in ['default','fleet']:
            gate = Path(gate_paths[profile]['oracle'])
            assert (gate/'parity.json').is_file() and (gate/'execution-profiles.json').is_file(), gate
            assert json.loads((gate/'execution-profiles.json').read_text())['status'] == 'PASS', gate
    elif absent:
        raise ValueError('missing prior configured units: ' + name + ' ' + repr(sorted(absent)))
    staged[output] = current
    report[name] = {
        'inputs': [str(path) for path in paths],
        'prior_targets': len(previous['targets']), 'targets': len(current['targets']),
        'prior_source_files': len(previous['source_files']), 'source_files': len(current['source_files']),
        'prior_reports': len(previous['configured_targets']), 'reports': len(current['configured_targets']),
        'unaffected_prior_configured_units_preserved': True,
        'cli_role_aliases_compared_by_prior_canonical_label': name == 'aos-cli',
        'repaired_cli_feature_units': repaired,
        'inventory_sha256': hashlib.sha256((json.dumps(current,indent=2,sort_keys=True)+'\n').encode()).hexdigest(),
    }

assert set(staged) == {root / ('tools/bazel/metadata/' + name + '-inventory.json') for name in base_paths}
for output, value in staged.items():
    output.write_text(json.dumps(value,indent=2,sort_keys=True)+'\n')
(scratch / 'cli-feature-configured-inventory-refresh.json').write_text(
    json.dumps({'schema_version':1,'status':'PASS','families':report},indent=2,sort_keys=True)+'\n')
print('Validated and published',len(staged),'fresh configured source inventories')
